#!/usr/bin/env -S deno run --check --allow-write=. --allow-read=. --lock=./tools/deno.lock.json
// Copyright 2026 the Ende authors. MIT license.
// Runs the ende.sh install scripts (tools/install) against the published
// releases on every OS that has one.
import { createWorkflow, defineMatrix, step } from "jsr:@david/gagen@0.3.1";

const installPaths = [
  "tools/install/**",
  ".github/workflows/install_test.generated.yml",
];

// A release that is never deleted, to test installing a pinned version.
const pinnedVersion = "v2026.10.14";

const unixMatrix = defineMatrix({
  runner: ["ubuntu-latest", "ubuntu-24.04-arm", "macos-latest"],
});

const checkout = step({
  name: "Clone repository",
  uses: "actions/checkout@v6",
});

const workflow = createWorkflow({
  name: "install_test",
  permissions: { contents: "read" },
  on: {
    push: { branches: ["primary"], paths: installPaths },
    pull_request: { branches: ["primary"], paths: installPaths },
    workflow_dispatch: {},
  },
  jobs: [{
    id: "unix",
    name: `install.sh ${unixMatrix.runner}`,
    runsOn: unixMatrix.runner,
    timeoutMinutes: 10,
    strategy: { matrix: unixMatrix, failFast: false },
    steps: [
      checkout,
      step({
        name: "Install latest",
        run: [
          'export ENDE_INSTALL_ROOT="$RUNNER_TEMP/latest"',
          "sh tools/install/install.sh",
          'test "v$("$ENDE_INSTALL_ROOT/bin/ende" eval -p Ende.version.ende)" = "$(curl -fsSL https://dl.ende.sh/release-latest.txt)"',
        ],
      }),
      step({
        name: "Install pinned version through a pipe",
        run: [
          'export ENDE_INSTALL_ROOT="$RUNNER_TEMP/pinned"',
          `sh -s ${pinnedVersion} < tools/install/install.sh`,
          `test "v$("$ENDE_INSTALL_ROOT/bin/ende" eval -p Ende.version.ende)" = ${pinnedVersion}`,
        ],
      }),
    ],
  }, {
    id: "windows",
    name: "install.ps1 windows-latest",
    runsOn: "windows-latest",
    timeoutMinutes: 10,
    steps: [
      checkout,
      step({
        name: "Install latest (PowerShell 7)",
        shell: "pwsh",
        run: [
          '$env:ENDE_INSTALL_ROOT = "$env:RUNNER_TEMP\\latest"',
          "./tools/install/install.ps1",
          '$latest = (Invoke-RestMethod "https://dl.ende.sh/release-latest.txt").Trim()',
          '$got = & "$env:ENDE_INSTALL_ROOT\\bin\\ende.exe" eval -p Ende.version.ende',
          'if ("v$got" -ne $latest) { throw "installed v$got, expected $latest" }',
          'if (([Environment]::GetEnvironmentVariable("Path", "User") -split ";") -notcontains "$env:ENDE_INSTALL_ROOT\\bin") { throw "bin dir not on user PATH" }',
        ],
      }),
      step({
        name: "Install pinned version through iex (Windows PowerShell 5.1)",
        shell: "powershell",
        run: [
          '$env:ENDE_INSTALL_ROOT = "$env:RUNNER_TEMP\\pinned"',
          `$v = "${pinnedVersion}"`,
          "Get-Content -Raw tools/install/install.ps1 | Invoke-Expression",
          '$got = & "$env:ENDE_INSTALL_ROOT\\bin\\ende.exe" eval -p Ende.version.ende',
          `if ("v$got" -ne "${pinnedVersion}") { throw "installed v$got, expected ${pinnedVersion}" }`,
        ],
      }),
    ],
  }],
});

const header = "# GENERATED BY ./install_test.ts -- DO NOT DIRECTLY EDIT";

export function generate() {
  return workflow.toYamlString({ header });
}

export const INSTALL_TEST_YML_URL = new URL(
  "./install_test.generated.yml",
  import.meta.url,
);

if (import.meta.main) {
  workflow.writeOrLint({ filePath: INSTALL_TEST_YML_URL, header });
}
